   A task whose job folder got a new file shows a "New file" badge on its row / card, and a note at the top of the task drawer
   asking the office to review and complete the task. Nothing completes itself. Dismiss clears the note (cbs-file-alerts-act). */
(function () {
  if (window.__cbsFA) return; window.__cbsFA = 1;
  var PJ = (new URLSearchParams(location.search).get('job') || '').replace(/[^0-9A-Za-z-]/g, '');
  var A = [], busy = false, tm = null;
  function E(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function norm(s) { return String(s || '').replace(/\s+/g, ' ').trim().toLowerCase(); }
  var css = document.createElement('style');
  css.textContent = '.fabadge{display:inline-block;margin-left:6px;font-size:11px;font-weight:700;line-height:1.5;background:#fff1d6;color:#7a4b00;border:1px solid #f0c36d;border-radius:10px;padding:0 7px;vertical-align:middle;white-space:nowrap}'
    + '.fabn{margin:10px 16px;padding:10px 12px;border:1px solid #f0c36d;background:#fff8e6;border-radius:10px;font:14px system-ui,-apple-system,"Segoe UI",sans-serif;color:#3d4043;line-height:1.4}'
    + '.fabn b{display:block;margin-bottom:4px;color:#7a4b00}.fabn ul{margin:4px 0 6px;padding-left:18px}.fabn a{color:#1f4f86}'
    + '.fabn .fa-r{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:6px;font-size:13px;color:#5c5f62}'
    + '.fabn button{font:inherit;font-size:13px;font-weight:600;border:1px solid #c4c6c8;background:#fff;border-radius:8px;padding:5px 12px;cursor:pointer;white-space:nowrap}';
  document.head.appendChild(css);
  function forTask(job, title) { title = norm(title); if (!job || !title) return []; return A.filter(function (a) { return String(a.job) === String(job) && norm(a.title) === title; }); }
  function jobIn(t) { var m = String(t || '').match(/Job ([0-9A-Za-z-]+)/); return m ? m[1] : PJ; }
  function titleOf(b) { var t = ''; [].forEach.call(b.childNodes, function (n) { if (!(n.nodeType === 1 && n.classList && n.classList.contains('fabadge'))) t += n.textContent; }); return t; }
  function paint() {
    [].forEach.call(document.querySelectorAll('.tki,.cd'), function (el) {
      var b = el.querySelector('b'); if (!b) return;
      var sm = el.querySelector('small'), job = el.classList.contains('cd') ? jobIn(sm ? sm.textContent : '') : PJ;
      var L = el.classList.contains('dn') ? [] : forTask(job, titleOf(b)), bd = b.querySelector('.fabadge');
      if (L.length) { if (!bd) { bd = document.createElement('span'); bd.className = 'fabadge'; b.appendChild(bd); } var tx = '\uD83D\uDCCE New file' + (L.length > 1 ? 's (' + L.length + ')' : ''); if (bd.textContent !== tx) bd.textContent = tx; bd.title = 'A file was uploaded for this task. Open the task to review and complete it.'; }
      else if (bd) bd.remove();
    });
    [].forEach.call(document.querySelectorAll('#ctd,#tkd,[role=dialog]'), function (d) {
      if (d.id === 'cbsTT') return;
      var hd = d.querySelector('.dh') || d.firstElementChild; if (!hd) return;
      var te = hd.querySelector('div[style*="font-size:18px"]') || hd.querySelector('h2,h3,b'); if (!te) return;
      var tt = te.tagName === 'INPUT' ? te.value : te.textContent, job = jobIn(hd.textContent);
      var L = forTask(job, tt), bn = d.querySelector('.fabn');
      if (!L.length) { if (bn) bn.remove(); return; }
      var key = L.map(function (a) { return a.id; }).join(',');
      if (bn && bn.getAttribute('data-k') === key) return; if (bn) bn.remove();
      bn = document.createElement('div'); bn.className = 'fabn'; bn.setAttribute('data-k', key);
      bn.innerHTML = '<b>\uD83D\uDCCE New file uploaded for this task</b><ul>' + L.map(function (a) { return '<li><a href="/webhook/cbs-file?u=' + encodeURIComponent(a.u) + '" target="_blank" rel="noopener">' + E(a.n) + '</a> <span style="color:#6b6e70">\u00b7 ' + E(a.folder) + (a.at ? ' \u00b7 ' + E(String(a.at).slice(8, 10) + '/' + String(a.at).slice(5, 7)) : '') + '</span></li>'; }).join('') + '</ul>'
        + '<div class="fa-r"><span>Check it and, if it finishes the task, complete the task below.</span><button type="button" class="fa-x">Dismiss</button></div>';
      hd.parentNode.insertBefore(bn, hd.nextSibling);
      bn.querySelector('.fa-x').onclick = function () {
        var btn = this; btn.disabled = true; var nm = ''; try { nm = localStorage.getItem('cbs_name') || ''; } catch (x) {}
        var ids = L.map(function (a) { return a.id; });
        fetch('/webhook/cbs-file-alerts-act', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ a: 'dismiss', ids: ids, by: nm }) })
          .then(function (r) { return r.json(); }).then(function (r) { if (!r || !r.ok) throw 0; A = A.filter(function (a) { return ids.indexOf(a.id) < 0; }); bn.remove(); paint(); })
          .catch(function () { btn.disabled = false; btn.textContent = 'Could not dismiss, try again'; });
      };
    });
  }
  function load() {
    if (busy) return; busy = true;
    fetch('/webhook/cbs-file-alerts' + (PJ ? '?job=' + encodeURIComponent(PJ) : ''), { cache: 'no-store' }).then(function (r) { return r.json(); })
      .then(function (d) { A = (d && d.alerts) || []; busy = false; paint(); }).catch(function () { busy = false; });
  }
  function later() { if (tm) return; tm = setTimeout(function () { tm = null; paint(); }, 120); }
  function start() { load(); setInterval(load, 60000); new MutationObserver(function (M) { for (var i = 0; i < M.length; i++) { var t = M[i].target; if (t && t.classList && (t.classList.contains('fabadge') || t.classList.contains('fabn'))) continue; later(); return; } }).observe(document.body, { childList: true, subtree: true }); }
  if (document.body) start(); else document.addEventListener('DOMContentLoaded', start);
})();

