/* Scan Plan: which jobs' files to list. Jobs with an open task that files can finish (same MAP as Scan Build). No fetching here:
   the task list comes from Scan Tasks and the file lists from Scan Files (HTTP Request nodes), so no Code step holds a Code slot. */
const H='https://old-hub.example/webhook/';const S=v=>v==null?'':String(v).trim();
const REQ={survey:1,estimate:1,supq:1,subq:1,docs:1,drawings:1,rams:1,subrams:1,pos:1,subpos:1,hire:1,inspection:1,scaffold:1,permits:1,cphsp:1,pci:1,inductions:1,toolbox:1,programme:1};
let D=null;try{const raw=$('Scan Tasks').first().json.data;D=typeof raw==='string'?JSON.parse(raw):raw;}catch(e){D=null;}
if(!D||!Array.isArray(D.tasks))return [];
const jobs={};D.tasks.forEach(t=>{const j=S(t.job),r=S(t.req);if(!j||!REQ[r])return;if(t.status==='Done'||t.status==='Verified')return;jobs[j]=1;});
const L=Object.keys(jobs).map(j=>({json:{job:j,u:H+'cbs-job-files?job='+encodeURIComponent(j)}}));
/* no jobs to check: one empty item so Scan Build still runs and clears alerts whose task is done */
return L.length?L:[{json:{job:'',u:''}}];

/* Scan Build (was Scan): every 15 minutes (and POST cbs-file-alerts-scan): for each job with an open task that files can finish (survey,
   quotes, RAMS, POs...), the job's files (listed by Scan Files) are checked and any file not seen before is logged in cbs_file_alerts. A file
   in a task's folder (e.g. Site Surveys -> Site survey) uploaded in the last 14 days while that task is open becomes an open alert (badge +
   note on the task, nothing closes itself). Everything else is logged as seen so it never alerts later. Open alerts whose task is now done
   or gone are cleared. Same rules as before; only the fetching moved to HTTP Request nodes (Scan Tasks, Scan Files). */
