const REQ={};Object.keys(MAP).forEach(k=>MAP[k].forEach(r=>REQ[r]=1));
const pj=raw=>{if(raw&&typeof raw==='object')return raw;if(typeof raw!=='string'||!raw.trim())return null;try{return JSON.parse(raw);}catch(e){return null;}};
let ex=[];try{ex=$('All Alerts').all().map(i=>i.json).filter(r=>r&&r.id!=null);}catch(e){}
const seen={};ex.forEach(r=>{seen[S(r.file_id)+'|'+S(r.req)]=1;});
let D=null;try{D=pj($('Scan Tasks').first().json.data);}catch(e){D=null;}
if(!D||!Array.isArray(D.tasks))return [];
const openT={};
D.tasks.forEach(t=>{const j=S(t.job),r=S(t.req);if(!j||!REQ[r])return;if(t.status==='Done'||t.status==='Verified')return;(openT[j+'|'+r]=openT[j+'|'+r]||[]).push(t);});
const out=[];
ex.forEach(r=>{if(S(r.status)==='open'&&!openT[S(r.job)+'|'+S(r.req)])out.push({json:{id:r.id,status:'cleared'}});});
const cut=new Date(Date.now()-14*864e5).toISOString(),now=new Date().toISOString();
const P=$('Scan Plan').all().map(i=>i.json||{});
$input.all().forEach(function(it,idx){
 const pi=(it.pairedItem&&typeof it.pairedItem.item==='number')?it.pairedItem.item:idx;const j=S((P[pi]||{}).job);if(!j)return;
 const x=it.json||{};if(x.error)return;const F=pj(x.data);
 if(!F||!F.ok||!Array.isArray(F.folders))return;
 F.folders.forEach(fd=>{const reqs=MAP[S(fd.name).toLowerCase()];if(!reqs)return;
  (fd.files||[]).forEach(f=>{const fid=S(f.id)||S(f.u);if(!fid)return;
   reqs.forEach(r=>{const k=fid+'|'+r;if(seen[k])return;seen[k]=1;const ot=openT[j+'|'+r],fresh=S(f.at)>=cut;
    out.push({json:{job:j,req:r,task_title:ot?S(ot[0].title):'',folder:S(fd.name),file_id:fid,file_name:S(f.n),file_url:S(f.u),file_at:S(f.at),status:(ot&&fresh)?'open':'seen',created_at:now,dismissed_by:''}});});});});});
return out;

const q=$('GET Alerts').first().json.query||{};const job=String(q.job||'').replace(/[^0-9A-Za-z-]/g,'');
let R=[];try{R=$('Alerts All').all().map(i=>i.json);}catch(e){}
const A=R.filter(r=>r&&r.id!=null&&r.status==='open'&&(!job||String(r.job)===job)).map(r=>({id:r.id,job:r.job,req:r.req,title:r.task_title,folder:r.folder,n:r.file_name,u:r.file_url,at:r.file_at}));
return [{json:{ok:true,alerts:A}}];

